import numpy as np

def detect_bias(data, protected_attribute, outcome):
    groups = np.unique(protected_attribute)
    total = len(protected_attribute)
    representation = {}
    outcome_rates = {}
    for g in groups:
        mask = protected_attribute == g
        representation[g] = np.sum(mask) / total
        outcome_rates[g] = np.mean(outcome[mask])
    max_rate = max(outcome_rates.values())
    disparity = {g: rate / max_rate for g, rate in outcome_rates.items()}
    return representation, outcome_rates, disparity
